export const getGetAchievementsUrl = (params: GetAchievementsParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/achievements?${stringifiedParams}`
    : `/api/achievements`;
};

export const getAchievements = async (
  params: GetAchievementsParams,
  options?: RequestInit,
): Promise<Achievement[]> => {
  return customFetch<Achievement[]>(getGetAchievementsUrl(params), {
    ...options,
    method: "GET",
  });
};

export const getGetAchievementsQueryKey = (params?: GetAchievementsParams) => {
  return [`/api/achievements`, ...(params ? [params] : [])] as const;
};

export const getGetAchievementsQueryOptions = <
  TData = Awaited<ReturnType<typeof getAchievements>>,
  TError = ErrorType<unknown>,
>(
  params: GetAchievementsParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof getAchievements>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey = queryOptions?.queryKey ?? getGetAchievementsQueryKey(params);

  const queryFn: QueryFunction<Awaited<ReturnType<typeof getAchievements>>> = ({
    signal,
  }) => getAchievements(params, { signal, ...requestOptions });

  return { queryKey, queryFn, ...queryOptions } as UseQueryOptions<
    Awaited<ReturnType<typeof getAchievements>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

export type GetAchievementsQueryResult = NonNullable<
  Awaited<ReturnType<typeof getAchievements>>
>;
export type GetAchievementsQueryError = ErrorType<unknown>;

/**
 * @summary Get user achievements
 */

export function useGetAchievements<
  TData = Awaited<ReturnType<typeof getAchievements>>,
  TError = ErrorType<unknown>,
>(
  params: GetAchievementsParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof getAchievements>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
): UseQueryResult<TData, TError> & { queryKey: QueryKey } {
  const queryOptions = getGetAchievementsQueryOptions(params, options);

  const query = useQuery(queryOptions) as UseQueryResult<TData, TError> & {
    queryKey: QueryKey;
  };

  return { ...query, queryKey: queryOptions.queryKey };
}
